"""Invoicer CLI — Click application with shared options."""

import os
from pathlib import Path

import click

DEFAULT_DATA_DIR = str(Path.home() / ".invoicer")


def _resolve_data_dir(ctx, param, value):
    """Resolve and return the data directory path."""
    if value is None:
        value = DEFAULT_DATA_DIR
    return Path(value)


class InvoicerGroup(click.Group):
    """Custom Click group that passes store_path to all subcommands via context."""

    def get_command(self, ctx, cmd_name):
        # Ensure the data_dir is available in the parent context for subcommands
        return super().get_command(ctx, cmd_name)


click_shared_options = [
    click.option(
        "--data-dir",
        type=click.Path(file_okay=False),
        default=None,
        callback=_resolve_data_dir,
        help="Directory for invoicer data files (default: ~/.invoicer).",
    ),
]


def _apply_shared_options(func):
    """Decorator that applies shared options to a Click command."""
    for option in reversed(click_shared_options):
        func = option(func)
    return func


@click.group(cls=InvoicerGroup, invoke_without_command=True)
@_apply_shared_options
@click.pass_context
def cli(ctx, data_dir):
    """Invoicer — a CLI invoicing tool."""
    ctx.ensure_object(dict)
    ctx.obj["data_dir"] = data_dir
    if ctx.invoked_subcommand is None:
        click.echo(ctx.get_help())


# Register all subcommands from the commands package.
from invoicer.commands import (
    add_client,
    create_invoice,
    export,
    list_invoices,
    mark_status,
    receipt,
    stats,
)

cli.add_command(add_client)
cli.add_command(create_invoice)
cli.add_command(export)
cli.add_command(list_invoices)
cli.add_command(mark_status)
cli.add_command(receipt)
cli.add_command(stats)

